import{d as a,S as n,i,l}from"./chunks/framework.CY2TYXqZ.js";const u=JSON.parse('{"title":"知的必要","description":"針對 FileHub 的黑箱滲透測試委託。這家檔案分享服務在產品頁上保證，某個帳號上傳的檔案只有該帳號讀得到。","frontmatter":{"title":"知的必要","number":1,"layout":"challenge","difficulty":"easy","category":"web","backend":"fastapi","app":"app.py","packages":[],"tools":["browser","network","repeater","code"],"source_visible":false,"date":"2026-04-02T08:54:17.674Z","tags":["idor","access-control","fastapi","sqlite"],"description":"針對 FileHub 的黑箱滲透測試委託。這家檔案分享服務在產品頁上保證，某個帳號上傳的檔案只有該帳號讀得到。","wasmModule":"/challenge/door-is-open/runtime.wasm","markdownBody":"\\n# 知的必要\\n\\n**委託單位：** FileHub，一家提供小型團隊使用的檔案分享服務。\\n**委託項目：** FileHub 網頁應用程式的黑箱滲透測試。\\n\\n## 測試範圍\\n\\n範圍內：本次來源（origin）底下的 FileHub 應用程式，以及它對外開放的每一個 HTTP 端點。\\n\\nFileHub 為本次委託配發給你一組帳號——帳號 `guest`，密碼 `guest`。這是一個沒有任何\\n額外權限的普通帳號，也是你手上唯一的憑證。\\n\\n範圍外：承載平台、其他委託案，以及阻斷服務。\\n\\n## 交戰規則\\n\\n這是一次獲得授權的演練，標的系統由 FileHub 自行掌控。達成目標後即停手——\\nFileHub 買的是「確實造成影響」的證明，不是破壞。請保持既有資料完整，並待在上述範圍內。\\n\\n本次委託 FileHub 沒有提供應用程式的原始碼。請以系統實際的回應為依據。\\n\\n## 委託目標\\n\\nFileHub 在產品頁上保證，某個帳號上傳的檔案只有該帳號讀得到。FileHub 自家的\\n工程師已經不相信這句話。\\n\\n請推翻這項保證：取得一份不屬於你的帳號的檔案內容。管理者把一份憑證存放在他的\\n私人檔案裡，取回那份內容就是 FileHub 認可的影響證明。請在下方送出，結案。\\n\\n## 交付項目\\n\\nFileHub 要的不只是結果，還有你怎麼走到那一步的紀錄。請把每一個推進測試的請求\\n記在筆記面板裡，結束時匯出整份 session。\\n"},"headers":[],"relativePath":"zh-TW/challenge/door-is-open/index.md","filePath":"zh-TW/challenge/door-is-open/index.md"}'),r={name:"zh-TW/challenge/door-is-open/index.md"};function o(t,e,s,d,p,c){return n(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="知的必要" tabindex="-1">知的必要 <a class="header-anchor" href="#知的必要" aria-label="Permalink to “知的必要”">​</a></h1><p><strong>委託單位：</strong> FileHub，一家提供小型團隊使用的檔案分享服務。 <strong>委託項目：</strong> FileHub 網頁應用程式的黑箱滲透測試。</p><h2 id="測試範圍" tabindex="-1">測試範圍 <a class="header-anchor" href="#測試範圍" aria-label="Permalink to “測試範圍”">​</a></h2><p>範圍內：本次來源（origin）底下的 FileHub 應用程式，以及它對外開放的每一個 HTTP 端點。</p><p>FileHub 為本次委託配發給你一組帳號——帳號 <code>guest</code>，密碼 <code>guest</code>。這是一個沒有任何 額外權限的普通帳號，也是你手上唯一的憑證。</p><p>範圍外：承載平台、其他委託案，以及阻斷服務。</p><h2 id="交戰規則" tabindex="-1">交戰規則 <a class="header-anchor" href="#交戰規則" aria-label="Permalink to “交戰規則”">​</a></h2><p>這是一次獲得授權的演練，標的系統由 FileHub 自行掌控。達成目標後即停手—— FileHub 買的是「確實造成影響」的證明，不是破壞。請保持既有資料完整，並待在上述範圍內。</p><p>本次委託 FileHub 沒有提供應用程式的原始碼。請以系統實際的回應為依據。</p><h2 id="委託目標" tabindex="-1">委託目標 <a class="header-anchor" href="#委託目標" aria-label="Permalink to “委託目標”">​</a></h2><p>FileHub 在產品頁上保證，某個帳號上傳的檔案只有該帳號讀得到。FileHub 自家的 工程師已經不相信這句話。</p><p>請推翻這項保證：取得一份不屬於你的帳號的檔案內容。管理者把一份憑證存放在他的 私人檔案裡，取回那份內容就是 FileHub 認可的影響證明。請在下方送出，結案。</p><h2 id="交付項目" tabindex="-1">交付項目 <a class="header-anchor" href="#交付項目" aria-label="Permalink to “交付項目”">​</a></h2><p>FileHub 要的不只是結果，還有你怎麼走到那一步的紀錄。請把每一個推進測試的請求 記在筆記面板裡，結束時匯出整份 session。</p>',14)])])}const h=a(r,[["render",o]]);export{u as __pageData,h as default};
